CREATE TABLE `worker_skills` (
  `worker_profile_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `skill_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`worker_profile_id`,`skill_id`),
  KEY `worker_skills_skill_id_fkey` (`skill_id`),
  CONSTRAINT `worker_skills_skill_id_fkey` FOREIGN KEY (`skill_id`) REFERENCES `skills` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `worker_skills_worker_profile_id_fkey` FOREIGN KEY (`worker_profile_id`) REFERENCES `worker_profiles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
